import itertools
from fractions import Fraction
from sympy import integer_nthroot, perfect_power

def geometric_means(values):
    """Return set of rational geometric means of all non-empty subsets."""
    n = len(values)
    gms = set()
    for size in range(1, n+1):
        for subset in itertools.combinations(range(n), size):
            prod = 1
            for idx in subset:
                prod *= values[idx]
            # Check if prod is a perfect `size`-th power
            root, is_perfect = integer_nthroot(prod, size)
            if is_perfect:
                gms.add(Fraction(root))
    return gms

def check(values):
    """Check if the condition holds for given values."""
    n = len(values)
    gms = geometric_means(values)
    for i in range(n):
        for j in range(i+1, n):
            am = Fraction(values[i] + values[j], 2)
            if am not in gms:
                return False
    return True

# Search for n=4 counterexamples (not all equal)
count = 0
for a,b,c,d in itertools.combinations_with_replacement(range(1, 50), 4):
    vals = [a,b,c,d]
    if len(set(vals)) == 1:
        continue
    if check(vals):
        print(f"n=4 counterexample: {vals}")
        count += 1
        if count >= 20:
            break

if count == 0:
    print("No n=4 counterexample found in range 1..49")
